"Conta come conversione il primo di questi eventi dopo l’invio ed entro N giorni (ora italiana): un incontro o una telefonata registrati sul contatto; una email registrata sul contatto con oggetto che inizia con «Re:», «R:» o «Risposta:»; una nuova trattativa sul contatto o sulla sua azienda. Ogni destinatario conta una volta; lo stesso evento può valere per più campagne ricevute dal contatto.":"The first of these events after the send and within N days (Italian time) counts as a conversion: a meeting or phone call logged on the contact; an email logged on the contact with a subject starting with «Re:», «R:» or «Risposta:»; a new deal on the contact or their company. Each recipient counts once; the same event can count for several campaigns received by the contact.",
