"Il primo clic di ogni persona su una campagna entra nella sua cronologia, alza il punteggio del contatto e crea un’attività «Richiama» per domani a chi gli ha scritto per ultimo. Alcuni filtri antivirus aprono i link da soli: un clic isolato subito dopo l’invio può non essere una persona. Date e finestre in ora italiana.":"Each person's first click on a campaign goes into their timeline, raises the contact score and creates a «Call back» task for tomorrow for whoever last wrote to them. Some antivirus filters open links by themselves: an isolated click straight after the send may not be a person. Dates and windows in Italian time.",
