"Si invia una email alla volta, ognuna con la sua conferma, oppure tutte insieme con «Invia a tutti» (una conferma, al massimo 200 per volta), oppure con «Metti in coda»: partono da sole dalle «Caselle email», in orario di lavoro e entro il limite giornaliero di ogni casella. Solo contatti con consenso marketing ed email valida; ogni email chiude con il link personale di disiscrizione. Ogni invio viene registrato come interazione.":"Emails are sent one at a time, each with its own confirmation, or all together with «Send to all» (one confirmation, up to 200 at a time), or with «Add to queue»: they go out by themselves from the «Mailboxes», during working hours and within each mailbox's daily limit. Only contacts with marketing consent and a valid email; every email ends with the personal unsubscribe link. Every send is logged as an activity.",
