"Il CRM ha più di 20.000 interazioni: il controllo dei duplicati guarda le più recenti 20.000.":"The CRM has more than 20,000 activities: the duplicate check looks at the most recent 20,000.",
"Aziende, contatti e trattative si collegano solo se esistono già nel CRM (contatto per email, poi per nome; maiuscole e accenti non contano): l’importazione non ne crea di nuovi. Una riga senza nessun collegamento viene saltata. Durata, esito e «assegnata a» finiscono nel testo dell’interazione. Date senza ora: alle 9:00.":"Companies, contacts and deals are linked only if they already exist in the CRM (contact by email, then by name; capitals and accents do not matter): the import does not create new ones. A row with no link at all is skipped. Duration, outcome and «assigned to» end up in the activity text. Dates without a time: at 9:00.",
