"Preventivi e fatture":"Quotes and invoices",
"La Regia qui legge soltanto: non invia email né messaggi LinkedIn, non avvia arricchimenti o verifiche a pagamento e non cambia i dati. Una bozza la scrivi come testo nella chat; l’invio si fa dal pulsante della pagina, con la sua conferma.":"Here the Regia only reads: it does not send emails or LinkedIn messages, does not start paid enrichments or checks and does not change data. You write a draft as text in the chat; sending is done from the page button, with its confirmation.",
