"Dove si blocca la pipeline?":"Where is the pipeline stuck?",
"Dove si blocca la pipeline? Guarda le fasi e le chiusure già passate e dimmi quali trattative muovere per prime. Le modifiche le faccio io dal CRM.":"Where is the pipeline stuck? Look at the stages and the closes already passed and tell me which deals to move first. I will make the changes from the CRM.",
