"Come importo i contatti da Sales Navigator in RADIX? Dammi i passi partendo da quello che vedo nella pagina.":"How do I import contacts from Sales Navigator into RADIX? Give me the steps starting from what I see on the page.",
"I contatti si importano con l’estensione «Importa in RADIX»; i messaggi LinkedIn si scrivono e si mandano da LinkedIn, a mano.":"Contacts are imported with the «Importa in RADIX» extension; LinkedIn messages are written and sent from LinkedIn, by hand.",
