"Come vanno le campagne? Per ogni campagna del progetto dimmi a che punto è, cosa manca (segmento, obiettivo, budget) e il prossimo passo.":"How are the campaigns going? For each campaign in the project tell me where it stands, what is missing (segment, goal, budget) and the next step.",
