"Quali lead lavoro prima? Metti in ordine i lead che vedi (email verificata, ruolo, azienda) e dimmi perché. Non avviare arricchimenti: se servono, dimmi quali e li avvio io dal pulsante.":"Which leads should I work on first? Rank the leads you see (verified email, role, company) and tell me why. Do not start enrichments: if they are needed, tell me which ones and I will start them from the button.",
