"Cosa è collegato":"What is connected",
"Il Copilota AI e il Riepilogo AI leggono i dati del CRM e non li modificano. Le email partono una alla volta, dopo una conferma, solo se l’invio Gmail è configurato; altrimenti si registrano soltanto. Con «Metti in coda» una campagna confermata parte dalle «Caselle email» del workspace, in orario di lavoro e con un limite giornaliero. Google Calendar e Outlook non sono sincronizzati: il calendario si esporta in .ics. Voce e documenti non sono integrati. I conteggi arrivano dal server; le schede mostrano solo le pagine caricate.":"The AI Copilot and the AI summary read the CRM data and do not change it. Emails go out one at a time, after a confirmation, only if Gmail sending is configured; otherwise they are only logged. With «Add to queue» a confirmed campaign goes out from the workspace «Mailboxes», during working hours and with a daily limit. Google Calendar and Outlook are not synchronised: the calendar is exported as .ics. Voice and documents are not integrated. Counts come from the server; the cards only show the loaded pages.",
"JavaScript è necessario. Accedi tramite la piattaforma e apri questa pagina sullo stesso dominio dell’API Sales.":"JavaScript is required. Sign in through the platform and open this page on the same domain as the Sales API.",
