"Importa o aggiungi i contatti.":"Import or add your contacts.",
"Crea le trattative e tienile aggiornate nella pipeline.":"Create deals and keep them up to date in the pipeline.",
"Chiedi al Copilota commerciale le priorità del giorno: risponde sui dati del tuo CRM.":"Ask the Sales Copilot for the day's priorities: it answers on your CRM data.",
"Le email partono da sole?":"Do emails go out by themselves?",
"No: ogni invio si conferma, e le campagne vanno solo ai contatti con consenso marketing.":"No: every send is confirmed, and campaigns only go to contacts with marketing consent.",
"La vista d’insieme commerciale: clienti e opportunità attorno al tuo business.":"The sales overview: customers and opportunities around your business.",
"Usala per capire dove concentrare il lavoro commerciale, poi apri il CRM per agire.":"Use it to see where to focus your sales work, then open the CRM to act.",
