"Scegli il progetto, crea la campagna in bozza e portala a «Pronta per revisione».":"Choose the project, create the campaign as a draft and take it to «Ready for review».",
"Importa in RADIX le persone trovate su Sales Navigator, con l’estensione «Importa in RADIX».":"Import into RADIX the people found on Sales Navigator, with the «Importa in RADIX» extension.",
