"Preventivi, fatture e listini dei prodotti del CRM.":"Quotes, invoices and product price lists of the CRM.",
"Crea il preventivo dai prodotti a listino; quando è accettato, fai la fattura.":"Create the quote from the listed products; when it is accepted, create the invoice.",
"Profilo e password, membri del workspace, caselle email del CRM, servizi collegati e regole del CRM.":"Profile and password, workspace members, CRM mailboxes, connected services and CRM rules.",
"In «Collegamenti» vedi quali servizi hanno la chiave configurata e quali mancano.":"In «Connections» you see which services have their key configured and which are missing.",
"In «Caselle email» owner e admin collegano le caselle da cui partono le campagne, con la password per le app.":"In «Mailboxes» owners and admins connect the mailboxes campaigns go out from, with the app password.",
"Come collego un servizio che manca?":"How do I connect a missing service?",
"Le chiavi dei servizi (Buffer, HeyGen, Higgsfield…) le aggiunge l’amministratore su Vercel: non si scrivono nell’app. Chiedi alla Regia «Cosa manca da collegare?» per i passi.":"Service keys (Buffer, HeyGen, Higgsfield…) are added by the administrator on Vercel: they are not typed into the app. Ask the Regia «What is left to connect?» for the steps.",
"Niente esce da RADIX (post, email, video) senza un clic di conferma di una persona.":"Nothing leaves RADIX (posts, emails, videos) without a person's confirmation click.",
"Le generazioni a pagamento (HeyGen, Higgsfield, immagini AI) chiedono sempre conferma prima di partire.":"Paid generations (HeyGen, Higgsfield, AI images) always ask for confirmation before starting.",
"Gli agenti scrivono solo con i fatti forniti: dove mancano lasciano [da fornire].":"Agents only write with the facts provided: where facts are missing they leave [to be provided].",
