"La trovi nell’elenco sotto: premi «Apri» e passi a rivedere i lead. Per più liste insieme spuntale e premi «Apri le liste selezionate».":"You will find it in the list below: press «Open» and move on to reviewing the leads. For several lists at once, tick them and press «Open the selected lists».",
