"Parti da un link LinkedIn":"Start from a LinkedIn link",
"Incolla un URL di ricerca/lista Sales Navigator o di profilo/azienda LinkedIn. Il collegamento da solo NON dà accesso ai risultati riservati. Importa qui righe CSV/TSV esportate lecitamente o incollate da te, senza condividere password o cookie. Nessun accesso automatico a LinkedIn.":"Paste a Sales Navigator search/list URL or a LinkedIn profile/company URL. The link alone does NOT give access to restricted results. Import here CSV/TSV rows exported lawfully or pasted by you, without sharing passwords or cookies. No automatic access to LinkedIn.",
"URL fonte LinkedIn / Sales Navigator":"LinkedIn / Sales Navigator source URL",
"Verifica URL":"Check URL",
"Apri LinkedIn ↗":"Open LinkedIn ↗",
"Il link viene analizzato localmente, senza essere aperto automaticamente.":"The link is analysed locally, without being opened automatically.",
"Importa righe CSV/TSV incollate (intestazioni name, domain, country, industry, companySize, contactRole, source)":"Import pasted CSV/TSV rows (headers name, domain, country, industry, companySize, contactRole, source)",
"＋ Importa righe nella lista":"＋ Import rows into the list",
"Per i file Excel o CSV esportati usa «File CSV/Excel» qui sopra. Questa parte non legge o automatizza la sessione LinkedIn.":"For exported Excel or CSV files use «CSV/Excel file» above. This part does not read or automate the LinkedIn session.",
"Importazione da provider esterno":"Import from an external provider",
"Se utilizzi un provider autorizzato a esportare risultati, puoi importare il JSON restituito da Captain Data, PhantomBuster o un servizio compatibile. RADIX non si collega al tuo account LinkedIn, non esegue scraping e non avvia alcun servizio a pagamento.":"If you use a provider authorised to export results, you can import the JSON returned by Captain Data, PhantomBuster or a compatible service. RADIX does not connect to your LinkedIn account, does not scrape and does not start any paid service.",
"Formato provider":"Provider format",
"JSON generico":"Generic JSON",
"Risultati provider (.json)":"Provider results (.json)",
"Seleziona il provider, incolla l'URL sorgente e importa un risultato autorizzato.":"Select the provider, paste the source URL and import an authorised result.",
"Collegamento a un agente browser":"Connection to a browser agent",
"Puoi far preparare a un agente browser un file JSON con i dati a cui hai diritto di accesso, senza fornire a RADIX password, cookie o sessioni LinkedIn. RADIX verifica lo schema, confronta l'URL di origine, esclude i duplicati e aggiunge i prospect solo dopo tua conferma. Non è un connettore automatico a LinkedIn.":"You can have a browser agent prepare a JSON file with the data you are entitled to access, without giving RADIX passwords, cookies or LinkedIn sessions. RADIX checks the schema, compares the source URL, excludes duplicates and adds the prospects only after your confirmation. It is not an automatic LinkedIn connector.",
"Copia istruzioni per l’agente":"Copy instructions for the agent",
"Apri URL nell’altra scheda":"Open URL in the other tab",
"Procedura guidata: 1. Inserisci e verifica la URL. 2. Aprila nel tuo browser già autenticato. 3. Acquisisci esclusivamente dati esportabili o utilizzabili con autorizzazione. 4. Restituisci il JSON secondo le istruzioni. 5. Incollalo o carica il file qui e approva prima di salvare. Non c'è lettura automatica della sessione LinkedIn.":"Guided procedure: 1. Enter and check the URL. 2. Open it in your browser where you are already signed in. 3. Acquire only data that can be exported or used with authorisation. 4. Return the JSON according to the instructions. 5. Paste it or upload the file here and approve before saving. There is no automatic reading of the LinkedIn session.",
"Importa risultati agente (.json)":"Import agent results (.json)",
"Oppure incolla qui il JSON restituito dall’agente":"Or paste the JSON returned by the agent here",
"Importa JSON incollato":"Import pasted JSON",
"Nessun file agente caricato.":"No agent file uploaded.",
"Anteprima acquisizione · nessuna modifica automatica":"Acquisition preview · no automatic changes",
