"(massimo 250 aziende; 1 MB per CSV, TSV e XLS, 3 MB per XLSX). CSV/TSV e XLSX vengono letti nel browser, senza trasmissione dei file. Il vecchio formato XLS richiede conversione temporanea sul server RADIX, soltanto dopo conferma esplicita.":"(250 companies maximum; 1 MB for CSV, TSV and XLS, 3 MB for XLSX). CSV/TSV and XLSX are read in the browser, without sending the files. The old XLS format requires temporary conversion on the RADIX server, only after explicit confirmation.",
