"Le liste possono contenere dati personali di contatto: rispettare base giuridica, scopi di utilizzo e cancellazione. Accesso riservato ai membri del workspace; sola lettura per il ruolo viewer. Nessuna operazione genera invii email.":"Lists may contain personal contact data: respect the legal basis, purposes of use and deletion. Access restricted to workspace members; read only for the viewer role. No operation sends emails.",
