"Completa i dati mancanti (secondo file, ricerca dei siti)":"Complete the missing data (second file, website search)",
"Carica una seconda lista CSV, TSV o XLSX contenente dati aggiuntivi. RADIX abbina per dominio o nome azienda univoco, individua i campi vuoti e propone le informazioni da valutare. Nessuna proposta sovrascrive campi già compilati, nessun dato viene cercato o inventato automaticamente sul web.":"Upload a second CSV, TSV or XLSX list containing additional data. RADIX matches by domain or unique company name, finds the empty fields and suggests the information to review. No suggestion overwrites fields already filled in, and no data is searched for or made up automatically on the web.",
"Ricerca pubblica automatica · Wikidata":"Automatic public search · Wikidata",
"RADIX può cercare fino a 5 aziende per volta su Wikidata e proporre il loro sito ufficiale quando manca. Serve un workspace autorizzato. I suggerimenti non sono verifiche definitive e non vengono applicati automaticamente. I nomi aziendali vengono trasmessi al servizio pubblico Wikidata.":"RADIX can look up to 5 companies at a time on Wikidata and suggest their official website when it is missing. An authorised workspace is needed. The suggestions are not final checks and are not applied automatically. Company names are sent to the public Wikidata service.",
"✧ Cerca siti ufficiali (max 5)":"✧ Find official websites (max 5)",
