"Per ogni lead: azienda (nome, sito, settore), referente (nome, email, telefono, ruolo, profilo LinkedIn) e un’opportunità nella prima fase della pipeline. Doppioni saltati per email, profilo LinkedIn, oppure stesso nome nella stessa azienda (dominio o nome). Nessuna email viene inviata.":"For each lead: company (name, website, sector), contact (name, email, phone, role, LinkedIn profile) and a deal in the first pipeline stage. Duplicates are skipped by email, LinkedIn profile, or the same name at the same company (domain or name). No email is sent.",
