"La scheda CRM attuale memorizza il nome del referente, ma non il suo indirizzo email né la prova della fonte. Questi dati rimangono nella sessione di revisione, non vengono salvati nel CRM.":"The current CRM record stores the contact's name, but not their email address or proof of source. This data stays in the review session and is not saved in the CRM.",
