"Scegli un prospect qualificato e approvato, modifica il messaggio e genera una bozza con campi dinamici. Nessun messaggio viene inviato e non viene chiamato alcun modello AI esterno.":"Choose a qualified and approved prospect, edit the message and generate a draft with dynamic fields. No message is sent and no external AI model is called.",
"Template email":"Email template",
"Buongiorno, ho notato che {azienda} opera nel settore {settore} in {paese}. Lavoro con aziende che desiderano migliorare i propri processi commerciali e vorrei capire se il tema può essere rilevante per il ruolo di {ruolo}. Le andrebbe un breve confronto? Cordiali saluti":"Good morning, I noticed that {azienda} operates in the {settore} sector in {paese}. I work with companies that want to improve their sales processes and would like to understand whether this could be relevant for the role of {ruolo}. Would you be open to a short conversation? Kind regards",
"Copia bozza":"Copy draft",
"Le variabili disponibili sono {azienda}, {settore}, {paese}, {ruolo}, {nome}, {email}. I campi mancanti bloccano la generazione.":"The available variables are {azienda}, {settore}, {paese}, {ruolo}, {nome}, {email}. Missing fields block generation.",
"Sequenza e follow-up":"Sequence and follow-up",
"NESSUN INVIO AUTOMATICO":"NO AUTOMATIC SENDING",
"Prepara tre bozze datate ed esporta il piano. Dopo aver collegato l'azienda al CRM puoi registrare il solo primo task oppure le tre attività (primo contatto e due follow-up). I task sono promemoria, non email automatiche. Ogni creazione richiede conferma.":"Prepare three dated drafts and export the plan. After linking the company to the CRM you can record just the first task or all three activities (first contact and two follow-ups). Tasks are reminders, not automatic emails. Every creation requires confirmation.",
