"Esiti e conversioni":"Outcomes and conversions",
"SOLO MANUALE":"MANUAL ONLY",
"Registra soltanto attività realmente avvenute. RADIX non invia email, non rileva risposte e non verifica conversioni. Puoi annullare l’ultimo esito dichiarato conservando la traccia della correzione nel CSV. Lo storico è temporaneo: esportalo prima di chiudere la pagina. Nessun dato personale aggiuntivo viene richiesto.":"Only record activities that really happened. RADIX does not send emails, detect replies or verify conversions. You can undo the last declared outcome while keeping a trace of the correction in the CSV. The history is temporary: export it before closing the page. No additional personal data is requested.",
