"Collega prima la scheda azienda CRM nel passaggio 05. Puoi salvare esplicitamente esiti e rettifiche nelle interazioni CRM, associate al workspace autorizzato. La consultazione ricostruisce lo storico registrato nel CRM, senza inventare comunicazioni, appuntamenti o conversioni. Non è ancora un sistema di analytics automatico.":"First link the CRM company record in step 05. You can explicitly save outcomes and corrections in the CRM interactions, tied to the authorised workspace. The view rebuilds the history recorded in the CRM, without inventing communications, meetings or conversions. It is not an automatic analytics system yet.",
