"Puoi usare l'estensione Chrome «Importa in RADIX» mentre navighi Sales Navigator con il tuo login, oppure un provider configurato per importare risultati nel motore contatti. Con l'estensione la sessione rimane nel tuo Chrome; nella modalità provider l'accesso è gestito dal servizio esterno. RADIX non richiede password o cookie.":"You can use the «Importa in RADIX» Chrome extension while you browse Sales Navigator with your own login, or a configured provider to import results into the contacts engine. With the extension the session stays in your Chrome; in provider mode access is handled by the external service. RADIX does not ask for passwords or cookies.",
