"L'estensione legge solo le pagine che apri tu e non raccoglie credenziali o cookie in RADIX. LinkedIn limita la raccolta automatica e può applicare restrizioni all'account: usala solo se autorizzato.":"The extension only reads the pages you open and does not collect credentials or cookies in RADIX. LinkedIn limits automated collection and may restrict the account: only use it if authorised.",
